/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=file, operation=delete
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Delete an activity */
export type PipedriveV2FileDeleteParams = {
  resource: 'file';
  operation: 'delete';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the file to delete
 * @default 0
 */
    fileId?: number | Expression<number>;
};

export type PipedriveV2FileDeleteNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2FileDeleteParams>;
};